# Double-check the Costas array [5, 9, 4, 6, 2, 0, 3, 8, 7, 1, 10]
perm = [5, 9, 4, 6, 2, 0, 3, 8, 7, 1, 10]
n = len(perm)

# Check it's a permutation
print("Sorted:", sorted(perm))
print("Is permutation:", sorted(perm) == list(range(n)))

# Check Costas property: all displacement vectors (dr, dc) with dc > 0 must be distinct
vectors = {}
for c1 in range(n):
    for c2 in range(c1+1, n):
        dr = perm[c2] - perm[c1]
        dc = c2 - c1
        if (dr, dc) in vectors:
            print(f"Duplicate vector ({dr}, {dc}) from columns ({c1}, {c2}) and {vectors[(dr, dc)]}")
        else:
            vectors[(dr, dc)] = (c1, c2)

print(f"Total vectors: {len(vectors)}")
print(f"Expected: {n*(n-1)//2}")
print("Is Costas:", len(vectors) == n*(n-1)//2)

# Print the grid representation
print("\nGrid (row, col):")
for r in range(n):
    row = []
    for c in range(n):
        if perm[c] == r:
            row.append('X')
        else:
            row.append('.')
    print(' '.join(row))
